def translate(text,s):
    text=str(text);index=2 if s.studio.guide_language=='BE' else 1
    exact=next((r[index] for r in ROWS if r[0]==text),None)
    if exact is not None:return exact
    for row in sorted(ROWS,key=lambda r:len(r[0]),reverse=True):
        if row[0] in text:text=text.replace(row[0],row[index])
    return text

_enum_cache=globals().get('_enum_cache',{})
def enum_choices(items):
    def choices(self,context):
        s=getattr(getattr(context,'scene',None),'color_prime',None)
        language=s.studio.guide_language if s else 'EN'
        key=('351',repr(items),language)
        if key not in _enum_cache:
            _enum_cache[key]=tuple((item[0],translate(item[1],s) if s else item[1],
                (('Выкарыстоўваць: ' if language=='BE' else 'Use: ')+(translate(item[1],s) if s else item[1])),index) for index,item in enumerate(items))
        return _enum_cache[key]
    return choices

class Layout:
    def __init__(self,layout,s):object.__setattr__(self,'_layout',layout);object.__setattr__(self,'_s',s)
    def __setattr__(self,key,value):setattr(self._layout,key,value)
    def __getattr__(self,name):
        value=getattr(self._layout,name)
        if not callable(value):return value
        def call(*args,**kw):
            if name in {'row','column','box','split','grid_flow','column_flow'}:return Layout(value(*args,**kw),self._s)
            if 'text' in kw:kw['text']=translate(kw['text'],self._s)
            elif name in {'prop','prop_search'} and len(args)>1:
                try:kw['text']=translate(args[0].bl_rna.properties[args[1]].name,self._s)
                except (AttributeError,KeyError):pass
            return value(*args,**kw)
        return call

